using System.Security.Claims;using EmployeeAttendanceSystem.Data;using EmployeeAttendanceSystem.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace EmployeeAttendanceSystem.Controllers;
[ApiController][Authorize(Roles="Employee,HR")][Route("api/attendance")]
public class AttendanceController:ControllerBase{readonly AttendanceService svc;readonly AppDbContext db;public AttendanceController(AttendanceService s,AppDbContext db){svc=s;this.db=db;}int U=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpPost("check-in")]public IActionResult In()=>Ok(svc.CheckIn(U));[HttpPost("check-out")]public IActionResult Out()=>Ok(svc.CheckOut(U));[HttpGet("today")]public IActionResult Today(){var a=db.Attendances.FirstOrDefault(x=>x.UserId==U&&x.Date==DateTime.Now.Date);return Ok(a);} [HttpGet("history")]public IActionResult History()=>Ok(db.Attendances.Where(x=>x.UserId==U).OrderByDescending(x=>x.Date).Take(90).ToList());}
